    private static String safeStop(Fixture f,String id,JSONObject actual)throws Exception {
        JSONObject original=f.tasks.ownerGitOriginalForOwner(id),row=original.getJSONObject("operation"),receipt=row.optJSONObject("receipt"),out=new JSONObject().put("taskId",id).put("taskStatus",original.getJSONObject("task").optString("status")).put("operationState",row.getString("state")).put("gitCode",actual.getJSONObject("git").optString("code"));
        JSONObject backend=receipt==null?null:receipt.optJSONObject("executionReceipt");
        if(backend!=null)for(String key:new String[]{"status","exitCode","terminationSignal","launchErrno","receiptReceived","resourcesReleased","processExited","processGroupAbsent","cancelRequested","noChildCreated","nativeResultContract","error"})if(backend.has(key))out.put(key,backend.get(key));
        out.put("callbackFailureType",f.callbackFailure.get()==null?JSONObject.NULL:f.callbackFailure.get().getClass().getSimpleName());
        if(f.callbackFailure.get()!=null)out.put("callbackSafeMessage",String.valueOf(f.callbackFailure.get().getMessage()).substring(0,Math.min(300,String.valueOf(f.callbackFailure.get().getMessage()).length())));
        JSONObject exact=ProjectDevelopment.exact(original.getJSONObject("plan"),ProjectGit.step(original.getJSONObject("plan")));try{JSONObject nativeNow=f.local.projectReceiptForHost(exact,original.getJSONObject("binding"),false),safe=new JSONObject();for(String key:new String[]{"status","exitCode","terminationSignal","launchErrno","receiptReceived","resourcesReleased","processExited","processGroupAbsent","cancelRequested","noChildCreated","error"})if(nativeNow.has(key))safe.put(key,nativeNow.get(key));safe.put("stdoutByteCount",nativeNow.optString("stdout").getBytes(StandardCharsets.UTF_8).length);out.put("actualNativeNow",safe);}catch(Exception failed){out.put("nativeReadException",failed.getClass().getSimpleName());}return out.toString();
    }
    @Test public void nativeOwnerActionUsesOriginalApprovalOneBudgetAndNeverBecomesARunnerOrReplays()throws Exception {
        try(Fixture f=new Fixture()){
            var request=f.local.reviewGitForOwner(f.checkout,new JSONObject().put("gitAction","status"));var confirmed=request.confirm();JSONObject result=f.finish(f.features.submitProjectGitForOwner(confirmed));f.success(result);String id=confirmed.requestId();JSONObject task=f.tasks.get(id,false);assertEquals("tool",task.getString("kind"));assertFalse(task.getJSONObject("ownerGit").getBoolean("modelDispatchAllowed"));assertEquals(1,task.getJSONArray("operations").length());assertEquals("receipt",task.getJSONArray("operations").getJSONObject(0).getString("state"));assertEquals("consumed",task.getJSONArray("approvals").getJSONObject(0).getString("state"));assertEquals(id,f.features.submitProjectGitForOwner(confirmed).getString("operationId"));assertEquals(1,f.tasks.get(id,false).getJSONArray("operations").length());assertThrows(Exception.class,()->f.tasks.startAttempt(id,"background",10));assertThrows(Exception.class,()->f.tasks.resolveOperation(id,id,"not_occurred"));
            EngineApplication app=new EngineApplication();app.tasks=f.tasks;app.features=f.features;assertThrows(Exception.class,()->app.dispatchOwnerAction("resumeTask",new JSONObject().put("taskId",id)));var workers=EngineApplication.class.getDeclaredField("capabilityWorkers");workers.setAccessible(true);((java.util.concurrent.ExecutorService)workers.get(app)).shutdownNow();
            var stale=f.local.reviewGitForOwner(f.checkout,new JSONObject().put("gitAction","status")).confirm();f.write("main.py","print('changed after owner review')\n");JSONObject failure=f.features.submitProjectGitForOwner(stale);assertEquals("project_git_preflight_rejected",failure.getJSONObject("git").getString("code"));assertEquals("failed",failure.getString("status"));assertEquals("receipt",f.tasks.get(stale.requestId(),false).getJSONArray("operations").getJSONObject(0).getString("state"));assertFalse(failure.getJSONObject("git").getBoolean("publicationUnknown"));assertNull(f.callbackFailure.get());
            System.out.println("C07_OWNER original FeatureHost beginExternal + immutable planRef + exact native owner approval consumed + one operation budget + original managed JNI result; same request only queries; no Runner/resume/reconciliation marker bypass; stale source definite before-runtime rejection. Host Linux, not ARM/UI/provider.");
        }
    }
    @Test public void realDualStatusSelectedCommitAndConflictResolveUseOriginalCasWithoutOverwritingOtherFiles()throws Exception {
        try(Fixture f=new Fixture()){
            f.seed();f.write("main.py","print('staged main')\n");f.write("other.py","print('staged other')\n");f.stage("main.py","other.py");f.write("main.py","print('newer working main')\n");JSONObject snapshot=f.status(),main=null;JSONArray entries=snapshot.getJSONArray("entries");for(int i=0;i<entries.length();i++)if(entries.getJSONObject(i).getString("path").equals("main.py"))main=entries.getJSONObject(i);assertNotNull(main);assertEquals("M",main.getString("indexStatus"));assertEquals("M",main.getString("worktreeStatus"));
            JSONObject staged=f.success(f.owner(new JSONObject().put("gitAction","diff").put("gitPin",snapshot.getJSONObject("pin")).put("path","main.py").put("gitLayer","head_index"))),working=f.success(f.owner(new JSONObject().put("gitAction","diff").put("gitPin",snapshot.getJSONObject("pin")).put("path","main.py").put("gitLayer","index_worktree")));assertTrue(staged.getString("diff").contains("+print('staged main')"));assertFalse(staged.getString("diff").contains("newer working"));assertTrue(working.getString("diff").contains("+print('newer working main')"));
            byte[] before=Files.readAllBytes(f.root.resolve(".git/index"));JSONObject selectedCommit=f.commit("main.py");JSONObject history=f.success(f.owner(new JSONObject().put("gitAction","history").put("gitPin",f.status().getJSONObject("pin"))));assertEquals(selectedCommit.getString("commitId"),history.getJSONArray("commits").getJSONObject(0).getString("commitId"));assertEquals(2,history.getJSONArray("commits").length());assertArrayEquals(before,Files.readAllBytes(f.root.resolve(".git/index")));assertEquals("print('staged main')",f.git("show","HEAD:main.py"));assertEquals("print('other')",f.git("show","HEAD:other.py"));assertEquals("print('newer working main')\n",readUtf8(f.root.resolve("main.py")));f.success(f.owner(f.selected("unstage","other.py")));assertEquals("print('staged other')\n",readUtf8(f.root.resolve("other.py")));
            // Only this self-created fixture uses direct Git to prepare a normal divergent merge.
            f.git("add","--","main.py","other.py");f.git("commit","-m","fixture baseline");f.git("checkout","-b","other");f.write("main.py","print('branch other')\n");f.git("commit","-am","other");f.git("checkout","main");f.write("main.py","print('branch main')\n");f.git("commit","-am","main");f.git("merge","other");JSONObject conflict=f.status();JSONObject draftReview=f.local.handle("reviewFile",f.input("main.py"));ProjectFileDraft draft=ProjectFileDraft.empty(f.project,f.checkout,"main.py",false).observe(draftReview).edit("print('owner solved after reading latest')\n");ProjectFileDraft.SaveIntent staleSave=draft.saveIntent();f.write("main.py","print('other owner source revision')\n");assertThrows(Exception.class,()->f.local.handle("writeFile",staleSave.input()));draft=draft.observe(f.local.handle("reviewFile",f.input("main.py")));assertTrue(draft.conflict());assertEquals("print('owner solved after reading latest')\n",draft.text);draft=draft.keepMineAgainstLatest();var selectedSave=draft.saveIntent();draft=draft.saved(selectedSave,f.local.handle("writeFile",selectedSave.input()));assertFalse(draft.dirty());
            JSONObject refreshed=f.status();f.success(f.owner(ProjectGit.selectionRequest(refreshed,"resolve",new JSONArray().put("main.py"))));JSONObject commit=f.commit("main.py");assertEquals(2,commit.getJSONArray("parents").length());assertEquals("print('owner solved after reading latest')",f.git("show","HEAD:main.py"));assertFalse(Files.exists(f.root.resolve(".git/MERGE_HEAD")));assertNull(f.callbackFailure.get());
            System.out.println("C07_REAL_GIT dual MM and exact two real diffs; selected original index tree/parents commit keeps other staged index bytes + newer worktree; conflict -> original draft stale CAS rejection/keep mine against latest -> original save -> explicit resolve -> real 2-parent commit. No push/clone/user repo/ARM proof.");
        }
    }
    @Test public void originalStopQueriesSameNativeRefAndIndexDriftOrUnknownLocksNeverGetOverwritten()throws Exception {
        try(Fixture f=new Fixture()){
            f.seed();f.write("main.py","print('first')\n");JSONObject old=f.selected("stage","main.py");f.write("main.py","print('newer')\n");byte[] index=Files.readAllBytes(f.root.resolve(".git/index"));JSONObject rejected=f.owner(old);assertFalse(rejected.getJSONObject("git").getBoolean("ok"));assertEquals("git_review_stale",rejected.getJSONObject("git").getString("code"));assertFalse(rejected.getJSONObject("git").getBoolean("publicationUnknown"));assertArrayEquals(index,Files.readAllBytes(f.root.resolve(".git/index")));
            writeUtf8(f.root.resolve(".git/index.lock"),"unknown owner lock");JSONObject locked=f.owner(f.selected("stage","main.py"));assertEquals("git_index_locked",locked.getJSONObject("git").getString("code"));assertEquals("unknown owner lock",readUtf8(f.root.resolve(".git/index.lock")));Files.delete(f.root.resolve(".git/index.lock"));
            var selected=f.local.reviewGitForOwner(f.checkout,new JSONObject().put("gitAction","status")).confirm();JSONObject started=f.features.submitProjectGitForOwner(selected);EngineApplication app=new EngineApplication();app.tasks=f.tasks;app.features=f.features;JSONObject stopped=app.dispatchOwnerAction("stopTask",new JSONObject().put("taskId",selected.requestId()));JSONObject finalResult=f.finish(stopped);assertEquals(selected.requestId(),finalResult.getString("operationId"));System.out.println("C07_STOP_ORIGINAL "+safeStop(f,selected.requestId(),finalResult));assertFalse("Original stop did not settle: "+safeStop(f,selected.requestId(),finalResult),f.tasks.hasUnresolved(selected.requestId()));JSONObject row=f.tasks.ownerGitOriginalForOwner(selected.requestId()).getJSONObject("operation").getJSONObject("receipt").getJSONObject("executionReceipt");assertTrue(row.getBoolean("resourcesReleased"));assertTrue(row.getBoolean("processGroupAbsent"));assertTrue(row.getBoolean("processExited")||dev.pocketengine.features.local.runtime.NativeProcessSupervisor.validatesNoChildReceipt(row));assertEquals(1,f.tasks.get(selected.requestId(),false).getJSONArray("operations").length());var workers=EngineApplication.class.getDeclaredField("capabilityWorkers");workers.setAccessible(true);((java.util.concurrent.ExecutorService)workers.get(app)).shutdownNow();assertNull(f.callbackFailure.get());
            System.out.println("C07_GUARDS real stale pins + unchanged index + unknown index.lock retained; actual App stop action routes original native Git ref, terminal requires real exit/no-child + group absence + lease release; no replay or claim that cancellation undid Git effects.");
        }
        // A real outer launcher can remain alive after the fixed child has emitted its final
        // result (PRoot is an Android example). This host-only controlled wrapper runs the exact
        // actual Python/Git program, then delays its own exit; it is not an alternative runtime.
        try(Fixture f=new Fixture(true)){
            f.seed();Files.createFile(f.temporary.resolve("delay-after-git-result"));var selected=f.local.reviewGitForOwner(f.checkout,new JSONObject().put("gitAction","status")).confirm();JSONObject started=f.features.submitProjectGitForOwner(selected),original=f.tasks.ownerGitOriginalForOwner(selected.requestId()),plan=original.getJSONObject("plan"),exact=ProjectDevelopment.exact(plan,ProjectGit.step(plan));
            JSONObject before=null;long until=System.nanoTime()+5_000_000_000L;while(System.nanoTime()<until){before=f.local.projectReceiptForHost(exact,original.getJSONObject("binding"),false);if(before.optString("stdout").contains("git_status_observed"))break;Thread.sleep(10);}
            assertNotNull(before);assertTrue("The fixed real child must have emitted its actual result before cancellation",before.optString("stdout").contains("git_status_observed"));assertFalse(before.getBoolean("resourcesReleased"));
            EngineApplication app=new EngineApplication();app.tasks=f.tasks;app.features=f.features;JSONObject stopped=app.dispatchOwnerAction("stopTask",new JSONObject().put("taskId",selected.requestId()));JSONObject actual=f.finish(stopped);String detail=safeStop(f,selected.requestId(),actual);System.out.println("C07_CONTROLLED_LATE_STOP "+detail);assertFalse(detail,f.tasks.hasUnresolved(selected.requestId()));assertEquals("paused",f.tasks.get(selected.requestId(),false).getString("status"));assertFalse(actual.getJSONObject("git").getBoolean("ok"));assertEquals("git_status_result_observed_process_failed",actual.getJSONObject("git").getString("code"));assertFalse(actual.getJSONObject("git").getBoolean("publicationUnknown"));assertFalse(actual.getJSONObject("git").getBoolean("nativeExecutionSuccessful"));
            JSONObject backend=f.tasks.ownerGitOriginalForOwner(selected.requestId()).getJSONObject("operation").getJSONObject("receipt").getJSONObject("executionReceipt");assertEquals("failed",backend.getString("status"));assertTrue(backend.getInt("exitCode")!=0||backend.getInt("terminationSignal")>0);assertTrue(backend.getBoolean("processExited")&&backend.getBoolean("processGroupAbsent")&&backend.getBoolean("resourcesReleased"));assertNull(f.callbackFailure.get());var workers=EngineApplication.class.getDeclaredField("capabilityWorkers");workers.setAccessible(true);((java.util.concurrent.ExecutorService)workers.get(app)).shutdownNow();
        }
    }
